def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    opp = [h[1] for h in history]
    me = [h[0] for h in history]
    if n < 3:
        return 'C'
    opp_def_total = sum(1 for a in opp if a == 'D')
    me_def_total = sum(1 for a in me if a == 'D')
    if n < 10:
        if opp[-1] == 'D':
            if n >= 2 and opp[-2] == 'D':
                return 'D'
            return 'D' if rng.random() < 0.6 else 'C'
        return 'C'
    recent_opp = opp[-10:]
    recent_me = me[-10:]
    opp_def10 = sum(1 for a in recent_opp if a == 'D')
    me_def10 = sum(1 for a in recent_me if a == 'D')
    opp_def5 = sum(1 for a in opp[-5:] if a == 'D')
    last_opp = opp[-1]
    last_me = me[-1]
    remaining = 100 - n
    if remaining <= 3:
        return 'D'
    if opp_def10 >= 9:
        return 'D'
    if opp_def10 <= 1 and n >= 20:
        if remaining <= 12:
            return 'D'
        if me_def_total <= 2 and rng.random() < 0.06:
            return 'D'
        return 'C'
    if last_opp == 'D' and last_me == 'C':
        if opp_def10 <= 2:
            return 'C'
        if rng.random() < 0.75:
            return 'D'
        return 'C'
    if last_opp == 'D' and last_me == 'D':
        if opp_def5 <= 1:
            return 'C'
        if opp_def10 >= 7:
            return 'D'
        if rng.random() < 0.4:
            return 'C'
        return 'D'
    if last_opp == 'C':
        if last_me == 'D':
            if opp_def10 >= 6:
                if rng.random() < 0.3:
                    return 'D'
            return 'C'
        if n >= 20:
            recent_opp_def_5 = sum(1 for a in opp[-5:] if a == 'D')
            earlier_opp_def = sum(1 for a in opp[-20:-5] if a == 'D')
            if recent_opp_def_5 >= 3 and earlier_opp_def <= 2:
                return 'D'
        if me_def10 >= 4 and rng.random() < 0.25:
            return 'D'
        if opp_def10 >= 5 and opp_def_total * 2 < n and rng.random() < 0.15:
            return 'D'
        return 'C'
    return 'C'
